   "titleVi": "V 出 + tân ngữ — làm ra, nghĩ ra",
   "giaiThich": "出 sau động từ vốn chỉ hướng từ trong ra ngoài (拿出). Ở bài này 出 chỉ kết quả: sau hành động thì SINH RA cái mới. Động từ hay dùng: 想, 做, 說, 穿, 拍, 寫, 找, 算, 研究."
