   "titleVi": "V 掉 — mất đi, bỏ đi",
   "giaiThich": "掉 là bổ ngữ. Sau ngoại động từ: bỏ đi, mất đi, thường là kết quả không mong muốn (吃掉, 扔掉, 賣掉). Sau nội động từ: rời đi (走掉, 飛掉, 跑掉, 壞掉)."
