   "titleVi": "NP 一 + lượng từ + 比 + 一 + lượng từ + Vs",
   "giaiThich": "Diễn đạt mức độ tăng dần theo từng đơn vị: \"cái sau hơn cái trước\" (一天比一天冷 — mỗi ngày một lạnh hơn)."
